/**
 * api.js — Axios instance for K2 Fast Foods.
 * Base URL comes from .env: REACT_APP_API_URL
 * Falls back to localhost:8080 path if not set.
 */
import axios from 'axios';

const BASE_URL =
  process.env.REACT_APP_API_URL ||
  'http://localhost:8080/k2fastfoods/backend/public/api/v1';

const api = axios.create({
  baseURL: BASE_URL,
  timeout: 15000,
  headers: {
    'Content-Type': 'application/json',
    'Accept': 'application/json',
    'Access-Control-Allow-Origin': '*',  // Allow all origins for CORS
  },
  withCredentials: false,  // must be false when CORS uses wildcard *
});

// Attach JWT token to every request
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('k2_token');
    if (token) {
      config.headers['Authorization'] = 'Bearer ' + token;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

// Handle 401 globally — clear token and redirect to login
api.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response && error.response.status === 401) {
      localStorage.removeItem('k2_token');
      localStorage.removeItem('k2_user');
      window.location.href = '/login';
    }
    return Promise.reject(error);
  }
);

export default api;
